import Foundation
import Metal

guard let device = MTLCreateSystemDefaultDevice() else {
    FileHandle.standardError.write(Data("Metal device unavailable\n".utf8))
    exit(2)
}
let library = try device.makeLibrary(URL: URL(fileURLWithPath: CommandLine.arguments[1]))
guard let function = library.makeFunction(name: "greeting"),
      let queue = device.makeCommandQueue(),
      let buffer = device.makeBuffer(length: 13, options: .storageModeShared),
      let command = queue.makeCommandBuffer(),
      let encoder = command.makeComputeCommandEncoder() else { exit(3) }
let pipeline = try device.makeComputePipelineState(function: function)
encoder.setComputePipelineState(pipeline)
encoder.setBuffer(buffer, offset: 0, index: 0)
encoder.dispatchThreads(MTLSize(width: 13, height: 1, depth: 1),
                        threadsPerThreadgroup: MTLSize(width: 13, height: 1, depth: 1))
encoder.endEncoding()
command.commit()
command.waitUntilCompleted()
guard command.status == .completed else { exit(4) }
let bytes = Data(bytes: buffer.contents(), count: 13)
guard let text = String(data: bytes, encoding: .utf8) else { exit(5) }
print(text)
